CnsMRParser::CnsMRParser(TokenStream *input) : CnsMRParser(input, antlr4::atn::ParserATNSimulatorOptions()) {}

CnsMRParser::CnsMRParser(TokenStream *input, const antlr4::atn::ParserATNSimulatorOptions &options) : Parser(input) {
  CnsMRParser::initialize();
  _interpreter = new atn::ParserATNSimulator(this, *cnsmrparserParserStaticData->atn, cnsmrparserParserStaticData->decisionToDFA, cnsmrparserParserStaticData->sharedContextCache, options);
}

CnsMRParser::~CnsMRParser() {
  delete _interpreter;
}

const atn::ATN& CnsMRParser::getATN() const {
  return *cnsmrparserParserStaticData->atn;
}

std::string CnsMRParser::getGrammarFileName() const {
  return "CnsMRParser.g4";
}

const std::vector<std::string>& CnsMRParser::getRuleNames() const {
  return cnsmrparserParserStaticData->ruleNames;
}

const dfa::Vocabulary& CnsMRParser::getVocabulary() const {
  return cnsmrparserParserStaticData->vocabulary;
}

antlr4::atn::SerializedATNView CnsMRParser::getSerializedATN() const {
  return cnsmrparserParserStaticData->serializedATN;
}


